            "stem": "IP 协议和UDP 协议都是一种不可靠的无连接数据报交付协议，使用无连接、不可靠传输服务的应用进程为什么不能直接使用IP 协议进行传输？",
            "answer": "IP协议实现主机到主机的通信，只能根据目的IP地址将数据送交给正确的主机。但是一台主机上可以并发运行多个应用进程，这些进程需要用端口地址来区分，所以必须使用UDP协议完成进程到进程的通信。"
