            "answer": "5G的应用场景分为三大类：增强移动带宽（enhanced Mobile Broadband，eMBB）、超高可靠低时延通信（Ultra Reliable and Low Latency Communication，URLLC）、海量物联网通信（massive Machine Type of Communication，mMTC），不同应用场景有着不同的关键能力要求。其中，峰值速率、时延、连接数密度是关键能力。eMBB场景下主要关注峰值速率和用户体验速率等，其中，5G的峰值速率相对于LTE的100Mbit/s提升了100倍，达到了10Gbit/s；URLLC场景下主要关注时延和移动性，其中，5G的空口时延相对于LTE的50ms降低到了1ms；mMTC场景下主要关注连接数密度，5G的每平方千米连接数相对于LTE的104个提升到了106个。"
